 public static void main(String[]args)throws Exception{Map<String,byte[]>out=new TreeMap<>();try(ZipFile z=new ZipFile(args[1])){for(ZipEntry e:Collections.list(z.entries())){byte[]b=z.getInputStream(e).readAllBytes();out.put(e.getName(),e.getName().endsWith(".class")?patch(b,args[0]):b);}}if(args[0].equals("firstaid"))out.put("dev/zomboid/firstaid/MedicineEvents33.class",medicineEvents());String prefix=args[0].equals("hordes")?"dev/zomboid/hordes/":args[0].equals("remains")?"dev/zomboid/remains/":args[0].equals("npc")?"mod/cdv/tnpc/tactical/":args[0].equals("firstaid")?"dev/zomboid/firstaid/":"com/raiiiden/warborn/common/util/";try(var files=Files.walk(Path.of(args[3]))){for(Path p:files.filter(p->p.toString().endsWith(".class")).toList()){String n=Path.of(args[3]).relativize(p).toString();if(n.startsWith(prefix))out.put(n,Files.readAllBytes(p));}}try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(args[2])))){for(var e:out.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}System.out.println("Verified "+hooks+" hooks.");}
